  if (head == NULL) {
    return head;
  }
  struct ListNode *tail = head;
  for (int i = 0; i < k; i++) {
    if (tail == NULL) {
      return head;
    }
    tail = tail->next;
  }
  struct ListNode *cur = head, *pre = NULL, *next = NULL;
  while (cur != tail) {
    next = cur->next;
    cur->next = pre;
    pre = cur;
    cur = next;
  }
  head->next = reverseKGroup(tail, k);
  return pre;
}

