}

class Solution {
  public ListNode reverseKGroup(ListNode head, int k) {
    if (head == null) {
      return head;
    }
    ListNode tail = head;
    for (int i = 0; i < k; i++) {
      if (tail == null) {
        return head;
      }
      tail = tail.next;
    }
    ListNode cur = head, pre = null, next = null;
    while (cur != tail) {
      next = cur.next;
      cur.next = pre;
      pre = cur;
      cur = next;
    }
    head.next = reverseKGroup(tail, k);
    return pre;
  }
}

class Solution:
    def reverseKGroup(self, head: ListNode, k: int) -> ListNode:
        if head is None:
            return head
        tail = head
        for _ in range(k):
            if tail is None:
                return head
            tail = tail.next
        pre, cur = None, head
        while cur is not tail:
            nxt = cur.next
            cur.next = pre
            pre = cur
            cur = nxt
        head.next = self.reverseKGroup(tail, k)
        return pre

impl Solution {
  pub fn reverse_k_group(head: Option<Box<ListNode>>, k: i32) -> Option<Box<ListNode>> {
    let mut vals = vec![];
    let mut cur = head;
    while let Some(node) = cur {
      vals.push(node.val);
      cur = node.next;
    }

    let k = k as usize;
    let mut i = 0;
    while i + k <= vals.len() {
      vals[i..i + k].reverse();
      i += k;
    }

    let mut dummy = ListNode::new(0);
    let mut tail = &mut dummy;
    for v in vals {
      tail.next = Some(Box::new(ListNode::new(v)));
      tail = tail.next.as_mut().unwrap();
    }
    dummy.next
  }
}

const reverseKGroup = (head: ListNode | null, k: number): ListNode | null => {
  if (head === null) return head;
  let tail: ListNode | null = head;
  for (let i = 0; i < k; i++) {
    if (tail === null) return head;
    tail = tail.next;
  }
  let cur: ListNode | null = head;
  let pre: ListNode | null = null;
  while (cur !== tail) {
    const next: ListNode | null = cur!.next;
    cur!.next = pre;
    pre = cur;
    cur = next;
  }
  head.next = reverseKGroup(tail, k);
  return pre;
};
